input.content:
'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const current = cookieStore.get('notifications')?.value === 'on'
  cookieStore.set('notifications', current ? 'off' : 'on')
  refresh()
}

import { cookies } from 'next/headers'
import { toggleNotificationPreference } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get('notifications')?.value === 'on'

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications: <strong>{enabled ? 'On' : 'Off'}</strong>
      </p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
